 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, ClampToEdgeWrapping, SRGBColorSpace } = THREE;

  const group = new Group();
  group.userData.handlers = {};
  group.renderOrder = 10;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelItem =
    items.find((i) => i.role === 'headline' && i.text) || items[0] || {
      text: 'Journal',
      typography: { fontSize: 96 },
    };

  const region = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = region.w / region.h;
  const spriteHeight = 2.0;
  const spriteWidth = spriteHeight * aspect;

  const geometry = new PlaneGeometry(spriteWidth, spriteHeight);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.FrontSide,
    depthTest: true,
    depthWrite: true,
  });

  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  const label = ctx.fontAtlas.createText(labelItem.text, {
    fontSize: labelItem.typography?.fontSize ?? 96,
    color: colors.paper,
    align: 'center',
  });
  label.position.z = 0.05;
  group.add(label);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (!plane.parent) return;

      const map = texture.clone();
      map.colorSpace = SRGBColorSpace;
      map.wrapS = ClampToEdgeWrapping;
      map.wrapT = ClampToEdgeWrapping;
      map.offset.set(region.x / texture.image.width, region.y / texture.image.height);
      map.repeat.set(region.w / texture.image.width, region.h / texture.image.height);
      map.needsUpdate = true;

      material.map = map;
      plane.userData.atlasMap = map;
    });
  }

  group.onBeforeRender = (renderer, scene, camera) => {
    group.lookAt(camera.position);
  };

  const timelines = [];
  group.userData.cleanup = () => {
    group.onBeforeRender = null;

    timelines.forEach((t) => t && t.kill && t.kill());
    timelines.length = 0;

    if (plane.userData.atlasMap) {
      plane.userData.atlasMap.dispose();
      plane.userData.atlasMap = null;
    }

    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material && obj !== plane) {
        obj.material.dispose();
      }
    });

    plane.material.dispose();
    plane.geometry.dispose();

    if (group.parent) group.parent.remove(group);
  };

  return group;
}
